from datetime import datetime, timedelta

def parse(path):
    ev=[]; cur=None
    for line in open(path):
        line=line.strip()
        if line=='BEGIN:VEVENT': cur={}
        elif line=='END:VEVENT': ev.append(cur); cur=None
        elif cur is not None and ':' in line:
            k,v=line.split(':',1); cur[k]=v
    out=[]
    for e in ev:
        s=datetime.strptime(e['DTSTART'],'%Y%m%dT%H%M%SZ')
        t=datetime.strptime(e['DTEND'],'%Y%m%dT%H%M%SZ')
        out.append((s,t,e.get('SUMMARY','')))
    return out

alice=parse('/app/alice_calendar.ics')
bob=parse('/app/bob_calendar.ics')
carol=parse('/app/carol_calendar.ics')

def busy(evs,s,e): return any(s<te and t>e for (ts,te,_) in evs for _ in [0]) and False or any(s<te and t>e for (ts,te,_) in evs)

def overlaps(evs,s,e):
    return any(s < te and e > ts for (ts,te,_) in evs)

days=[datetime(2024,1,15)+timedelta(days=i) for i in range(5)]

def valid(s):
    e=s+timedelta(hours=1)
    d=s.date()
    wd=s.weekday()  # 0 Mon
    # business hours
    if not (s.time()>=datetime.strptime('09:00','%H:%M').time() and e.time()<=datetime.strptime('18:00','%H:%M').time() and e.date()==d):
        return False,'hours'
    # Alice hard: 9-14
    if s.hour<9 or e>datetime.combine(d,datetime.strptime('14:00','%H:%M').time()):
        return False,'alice hard'
    # Bob no before 10
    if s < datetime.combine(d,datetime.strptime('10:00','%H:%M').time()):
        return False,'bob hard'
    # Bob Tue/Thu leave by 16:30
    if wd in (1,3) and e > datetime.combine(d,datetime.strptime('16:30','%H:%M').time()):
        return False,'bob tue/thu'
    # Carol 9-17, lunch 12-12:30
    if s < datetime.combine(d,datetime.strptime('09:00','%H:%M').time()) or e > datetime.combine(d,datetime.strptime('17:00','%H:%M').time()):
        return False,'carol hours'
    lunch=(datetime.combine(d,datetime.strptime('12:00','%H:%M').time()),datetime.combine(d,datetime.strptime('12:30','%H:%M').time()))
    if s < lunch[1] and e > lunch[0]:
        return False,'carol lunch'
    if overlaps(alice,s,e): return False,'alice conflict'
    if overlaps(bob,s,e): return False,'bob conflict'
    if overlaps(carol,s,e): return False,'carol conflict'
    # Carol buffer after meetings ending >=16:45 (new meeting)
    if e.time() >= datetime.strptime('16:45','%H:%M').time():
        pass # buffer after would exceed 17:00 availability; handled by carol hours since e<=17:00; if e==17:00 buffer violates
    return True,'ok'

found=[]
t=datetime(2024,1,15,9,0)
end=datetime(2024,1,20,0,0)
while t<end:
    ok,why=valid(t)
    if ok: found.append(t)
    t+=timedelta(minutes=1)
print("total valid start minutes:",len(found))
if found:
    print("earliest valid:",found[0], "latest:",found[-1])
# group earliest by day
seen=set()
for f in found:
    if f.date() not in seen:
        seen.add(f.date()); print("first each day:",f, f.strftime('%A'))
